-- V1.13 additive read-only position intelligence. Snapshot retention is opt-in.
CREATE TABLE defi_protocols (id text PRIMARY KEY, name text NOT NULL, official_url text NOT NULL);
CREATE TABLE defi_adapter_versions (adapter text NOT NULL, version text NOT NULL, PRIMARY KEY(adapter,version));
CREATE TABLE defi_protocol_sources (source_hash text PRIMARY KEY CHECK(source_hash ~ '^[a-f0-9]{64}$'), url text NOT NULL, revision text NOT NULL, fetched_at timestamptz NOT NULL, terms_status text NOT NULL);
CREATE TABLE defi_protocol_deployments (id text PRIMARY KEY, protocol_id text NOT NULL REFERENCES defi_protocols(id), chain_id text NOT NULL, adapter text NOT NULL, version text NOT NULL, contracts jsonb NOT NULL, official_source text NOT NULL, revision text NOT NULL, environment text NOT NULL CHECK(environment='mainnet'), status text NOT NULL, FOREIGN KEY(adapter,version) REFERENCES defi_adapter_versions(adapter,version));
CREATE TABLE defi_position_refs (deployment_id text NOT NULL REFERENCES defi_protocol_deployments(id), position_key text NOT NULL, contract text, market_id text, source_block numeric(78,0) NOT NULL, source_hash text NOT NULL, PRIMARY KEY(deployment_id,position_key));
CREATE TABLE defi_scan_runs (id text PRIMARY KEY, client_scope text NOT NULL, wallet_hash text NOT NULL, started_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, state text NOT NULL, rpc_calls integer NOT NULL CHECK(rpc_calls>=0));
CREATE TABLE defi_scan_coverage (scan_id text NOT NULL REFERENCES defi_scan_runs(id) ON DELETE CASCADE, deployment_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(scan_id,deployment_id));
CREATE TABLE defi_position_snapshots (scan_id text NOT NULL REFERENCES defi_scan_runs(id) ON DELETE CASCADE, position_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(scan_id,position_id));
CREATE TABLE defi_position_assets (scan_id text NOT NULL, position_id text NOT NULL, ordinal integer NOT NULL, role text NOT NULL, asset_id text NOT NULL, raw_amount numeric(78,0) NOT NULL CHECK(raw_amount>=0), payload jsonb NOT NULL, PRIMARY KEY(scan_id,position_id,ordinal), FOREIGN KEY(scan_id,position_id) REFERENCES defi_position_snapshots(scan_id,position_id) ON DELETE CASCADE);
CREATE TABLE defi_position_rewards (scan_id text NOT NULL, position_id text NOT NULL, ordinal integer NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(scan_id,position_id,ordinal), FOREIGN KEY(scan_id,position_id) REFERENCES defi_position_snapshots(scan_id,position_id) ON DELETE CASCADE);
CREATE TABLE defi_position_risk (scan_id text NOT NULL, position_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(scan_id,position_id), FOREIGN KEY(scan_id,position_id) REFERENCES defi_position_snapshots(scan_id,position_id) ON DELETE CASCADE);
CREATE TABLE defi_event_checkpoints (deployment_id text PRIMARY KEY REFERENCES defi_protocol_deployments(id), indexed_from numeric(78,0) NOT NULL, indexed_through numeric(78,0) NOT NULL, block_hash text NOT NULL, historical_complete boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE defi_event_windows (deployment_id text NOT NULL, from_block numeric(78,0) NOT NULL, to_block numeric(78,0) NOT NULL, block_hash text NOT NULL, PRIMARY KEY(deployment_id,to_block));
CREATE TABLE erc721_transfers (deployment_id text NOT NULL REFERENCES defi_protocol_deployments(id), block_number numeric(78,0) NOT NULL, block_hash text NOT NULL, tx_hash text NOT NULL, log_index integer NOT NULL, collection text NOT NULL, token_id numeric(78,0) NOT NULL, from_address text NOT NULL, to_address text NOT NULL, PRIMARY KEY(deployment_id,tx_hash,log_index));
CREATE TABLE wallet_nft_positions (deployment_id text NOT NULL REFERENCES defi_protocol_deployments(id), collection text NOT NULL, token_id numeric(78,0) NOT NULL, owner_address text NOT NULL, block_number numeric(78,0) NOT NULL, PRIMARY KEY(deployment_id,collection,token_id));
CREATE TABLE defi_position_nft_refs (deployment_id text NOT NULL, token_id numeric(78,0) NOT NULL, source_block numeric(78,0) NOT NULL, PRIMARY KEY(deployment_id,token_id));
CREATE TABLE wallet_protocol_activity (deployment_id text NOT NULL REFERENCES defi_protocol_deployments(id), wallet_address text NOT NULL, position_key text NOT NULL, source_block numeric(78,0) NOT NULL, tx_hash text NOT NULL, log_index integer NOT NULL, PRIMARY KEY(deployment_id,tx_hash,log_index));
CREATE INDEX defi_scan_expiry ON defi_scan_runs(expires_at);
CREATE INDEX defi_scope_wallet ON defi_scan_runs(client_scope,wallet_hash);
CREATE INDEX defi_nft_owner ON wallet_nft_positions(owner_address,deployment_id);
CREATE INDEX defi_activity_wallet ON wallet_protocol_activity(wallet_address,deployment_id);
